import json,os,re,collections
d=json.load(open(os.environ['TMPDIR']+'/w/pdf.json'))
prods=[json.loads(l) for l in open('shopify/products.jsonl')]
P={p['id']:p for p in prods if 'Product/' in p['id']}
desc={}
for v in prods:
    if 'Variant' in v['id']:
        p=P[v['__parentId']]
        desc[(p['title']+' '+v['title']).lower()]=v['sku']
rows=[]  # (sup, code, desc, hs, file)
for f,t in d.items():
    if not os.path.basename(f).startswith('CI-PL'): continue
    sup=re.search(r'Email: sales@(\w+)\.example',t).group(1).upper()
    ls=t.split('\n')
    for i,l in enumerate(ls):
        m=re.match(r'^(\S+) (.+?)$',l)
        if i+2<len(ls) and re.search(r'[一-鿿]',ls[i+1]) and re.match(r'^\d{4}\.\d{2}\.\d{4} ',ls[i+2]) and m:
            rows.append((sup,m.group(1),m.group(2).lower(),ls[i+2].split()[0],f))
print(len(rows))
m=collections.defaultdict(set);hs=collections.defaultdict(set)
for sup,c,ds,h,f in rows: m[(sup,c)].add(ds); hs[(sup,c)].add(h)
print(len(m),[k for k,v in m.items() if len(v)>1],[k for k,v in hs.items() if len(v)>1])
unm=[]
res={}
for k,v in sorted(m.items()):
    ds=list(v)[0]; s=desc.get(ds)
    if s is None: unm.append((k,ds))
    else: res[k]=s
print(len(res),'unmatched',unm)
print(len(set(res.values())))
print(sorted(set(desc)-set(' '.join([]) for _ in [])-{k for k in desc if desc[k] in res.values()}))
json.dump({'%s:%s'%k:[v,list(hs[k])[0]] for k,v in res.items()},open(os.environ['TMPDIR']+'/w/factory.json','w'))
