    P = {p['id']: p for p in prods if 'Product/' in p['id']}
    desc = {}
    for v in prods:
        if 'Variant' in v['id']:
            desc[(P[v['__parentId']]['title'] + ' ' + v['title']).lower()] = canon(v['sku'])
    seen = set()
    for f in sorted(d):
