            continue
        t = d[f]
        sup = re.search(r'Email: sales@(\w+)\.example', t).group(1).upper()
        ls = t.split('\n'); grp = []
        for i, l in enumerate(ls):
            m = re.match(r'^(\S+) (.+?)$', l)
            if i + 2 < len(ls) and re.search(r'[一-鿿]', ls[i + 1]) and re.match(r'^\d{4}\.\d{2}\.\d{4} ', ls[i + 2]) and m:
                code = '%s:%s' % (sup, m.group(1))
                if code in seen:
                    continue
                seen.add(code)
