    edges = {}
    for rule, m, conf in (('mail', mails, 0.9), ('nameaddr', na, 0.7)):
        for v in m.values():
            v = sorted(v, key=lambda k: (first[k], k))
            for k in v[1:]:
                edges[(v[0], k)] = max(edges.get((v[0], k), 0), conf)
