        g.append(gg)
    write('3pl/receipts.csv', g)
    out = list(csv.DictReader(open(os.path.join(EX, '3pl/outbound.csv'))))
    if LIMIT: out = out[:LIMIT]
    g, seen = [], set()
    for r in out:
        ref = r['Order Reference']
        k = '%s/%s' % (ref, r['Item Code'])
